"""
Customized Mixin2to3 support:

 - adds support for converting doctests


This module raises an ImportError on Python 2.
"""

import warnings
from distutils.util import Mixin2to3 as _Mixin2to3
from distutils import log
from lib2to3.refactor import RefactoringTool, get_fixers_from_package

import setuptools
from ._deprecation_warning import SetuptoolsDeprecationWarning


class DistutilsRefactoringTool(RefactoringTool):
    """类 DistutilsRefactoringTool：封装与该模块相关的数据与行为。"""
    def log_error(self, msg, *args, **kw):
        """函数 log_error：处理 msg, *args, **kw 相关逻辑。"""
        log.error(msg, *args)

    def log_message(self, msg, *args):
        """函数 log_message：处理 msg, *args 相关逻辑。"""
        log.info(msg, *args)

    def log_debug(self, msg, *args):
        """函数 log_debug：处理 msg, *args 相关逻辑。"""
        log.debug(msg, *args)


class Mixin2to3(_Mixin2to3):
    """类 Mixin2to3：封装与该模块相关的数据与行为。"""
    def run_2to3(self, files, doctests=False):
        """函数 run_2to3：处理 files, doctests 相关逻辑。"""
        # See of the distribution option has been set, otherwise check the
        # setuptools default.
        if self.distribution.use_2to3 is not True:
            return
        if not files:
            return

        warnings.warn(
            "2to3 support is deprecated. If the project still "
            "requires Python 2 support, please migrate to "
            "a single-codebase solution or employ an "
            "independent conversion process.",
            SetuptoolsDeprecationWarning)
        log.info("Fixing " + " ".join(files))
        self.__build_fixer_names()
        self.__exclude_fixers()
        if doctests:
            if setuptools.run_2to3_on_doctests:
                r = DistutilsRefactoringTool(self.fixer_names)
                r.refactor(files, write=True, doctests_only=True)
        else:
            _Mixin2to3.run_2to3(self, files)

    def __build_fixer_names(self):
        """函数 __build_fixer_names：核心业务逻辑。"""
        if self.fixer_names:
            return
        self.fixer_names = []
        for p in setuptools.lib2to3_fixer_packages:
            self.fixer_names.extend(get_fixers_from_package(p))
        if self.distribution.use_2to3_fixers is not None:
            for p in self.distribution.use_2to3_fixers:
                self.fixer_names.extend(get_fixers_from_package(p))

    def __exclude_fixers(self):
        """函数 __exclude_fixers：核心业务逻辑。"""
        excluded_fixers = getattr(self, 'exclude_fixers', [])
        if self.distribution.use_2to3_exclude_fixers is not None:
            excluded_fixers.extend(self.distribution.use_2to3_exclude_fixers)
        for fixer_name in excluded_fixers:
            if fixer_name in self.fixer_names:
                self.fixer_names.remove(fixer_name)
